/**
 * @name HTTP injection via headers, query params, or body
 * @description User-controlled data flowing into HTTP headers, query parameters, or request body could lead to injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/http-injection-comprehensive
 * @tags security
 *        external/cwe/cwe-113
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module HttpInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: HTTP request URL parameter
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["Client", "AsyncClient", "request", "get", "post", "put", "delete", "patch", "head", "options"]).getACall() and
      sink = call.getArg(0)  // URL parameter
    ) or
    // Sink: HTTP headers parameter
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["Client", "AsyncClient", "request", "get", "post", "put", "delete", "patch", "head", "options"]).getACall() and
      sink = call.getArg(1)  // headers parameter (usually second arg)
    ) or
    // Sink: HTTP request body/data parameter
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["Client", "AsyncClient", "request", "get", "post", "put", "delete", "patch", "head", "options"]).getACall() and
      sink = call.getArg(2)  // data/body parameter (usually third arg)
    ) or
    // Sink: Query parameters in URL construction
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember("_urls").getMember("URL").getACall() and
      sink = call.getArg(0)  // URL string parameter
    )
  }
}

module HttpInjectionFlow = TaintTracking::Global<HttpInjectionConfig>;
import HttpInjectionFlow::PathGraph

from HttpInjectionFlow::PathNode source, HttpInjectionFlow::PathNode sink
where HttpInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTTP injection from $@.", source.getNode(), "user input"

/**
 * @name Unsafe deserialization in HTTP response handling
 * @description Deserializing untrusted HTTP response data can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization-http
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UnsafeDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: HTTP response data
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["Response", "get", "post", "request"]).getACall() and
      source = DataFlow::exprNode(call.asExpr())  // Response object
    ) or
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: Unsafe deserialization functions
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("json").getMember("loads").getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeDeserializationFlow = TaintTracking::Global<UnsafeDeserializationConfig>;
import UnsafeDeserializationFlow::PathGraph

from UnsafeDeserializationFlow::PathNode source, UnsafeDeserializationFlow::PathNode sink
where UnsafeDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization from $@.", source.getNode(), "HTTP response"

/**
 * @name Path traversal in file operations
 * @description User-controlled data flowing into file operations could lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File open operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)  // file path
    ) or
    // Sink: os.path operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "rename", "stat", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)  // file path
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os.path").getMember(["join", "exists", "isfile", "isdir"]).getACall() and
      sink = call.getArg(0)  // path argument
    ) or
    // Sink: pathlib operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)  // path string
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"
